/** Job model, row mapping, and request validation shared by the server and the worker. */

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  next_run_at: number;
  created_at: string;
  updated_at: string;
}

/** The public JSON shape of a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface FieldError {
  field: string;
  message: string;
}

/** The submission after defaults are applied. */
export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

/** A transient failure is retried until this many attempts have been made in total. */
export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';
export const MAX_INPUT_LENGTH = 1000;

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function integerField(body: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
  const v = body[name];
  if (v === undefined) return fallback;
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return v;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

/** Validates a parsed request body. Returns every offending field, or the submission with defaults applied. */
export function parseSubmission(body: unknown): { ok: true; value: Submission } | { ok: false; fields: FieldError[] } {
  if (!isRecord(body)) return { ok: false, fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }
  const input = body.input;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'input is required' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `input must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'input must not be only whitespace' });
  }
  const steps = integerField(body, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(body, 'failAttempts', 0, 5, 0, fields);
  if (fields.length > 0 || typeof input !== 'string') return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

