import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { TRANSIENT_ERROR, toJob, type Job, type JobRow, type Submission } from './jobs.ts';

/** Every database operation used by the server and the worker. The two processes share nothing else. */

const HEARTBEAT_KEY = 'worker_heartbeat';

export type SubmitOutcome = { kind: 'created'; job: Job } | { kind: 'replayed'; job: Job } | { kind: 'conflict' };

function inTransaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

function rowById(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = rowById(db, id);
  return row ? toJob(row) : undefined;
}

export function listJobs(db: DatabaseSync): Job[] {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  return rows.map(toJob);
}

/** Creates a job, or replays/conflicts with an earlier job that used the same idempotency key. */
export function submitJob(db: DatabaseSync, submission: Submission, idempotencyKey: string | undefined): SubmitOutcome {
  return inTransaction(db, () => {
    if (idempotencyKey !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as JobRow | undefined;
      if (existing) {
        const same =
          existing.input === submission.input && existing.steps === submission.steps && existing.fail_attempts === submission.failAttempts;
        return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, next_run_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(id, submission.input, submission.steps, submission.failAttempts, idempotencyKey ?? null, now, now);
    return { kind: 'created', job: toJob(rowById(db, id)!) };
  });
}

/** A job claimed by the worker for one attempt. */
export interface ClaimedJob {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
}

/** Marks the oldest eligible queued job as running for a new attempt. Returns undefined when none is ready. */
export function claimNextJob(db: DatabaseSync, nowMs: number): ClaimedJob | undefined {
  const row = db
    .prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ?
       WHERE id = (SELECT id FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq LIMIT 1)
       RETURNING id, input, steps, fail_attempts, attempts`,
    )
    .get(new Date().toISOString(), nowMs) as
    | { id: string; input: string; steps: number; fail_attempts: number; attempts: number }
    | undefined;
  if (!row) return undefined;
  return { id: row.id, input: row.input, steps: row.steps, failAttempts: row.fail_attempts, attempts: row.attempts };
}

/** Returns jobs left `running` by a worker that died back to the queue, so they are processed again. */
export function recoverInterruptedJobs(db: DatabaseSync): void {
  db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, next_run_at = 0, updated_at = ? WHERE status = 'running'`).run(
    new Date().toISOString(),
  );
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
}

export function requeueJob(db: DatabaseSync, id: string, delayMs: number): void {
  db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, next_run_at = ?, updated_at = ? WHERE id = ?`).run(
    Date.now() + delayMs,
    new Date().toISOString(),
    id,
  );
}

export function completeJob(db: DatabaseSync, id: string, output: string, steps: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', result_output = ?, completed = ?, error = NULL, updated_at = ? WHERE id = ?`,
  ).run(output, steps, new Date().toISOString(), id);
}

export function failJob(db: DatabaseSync, id: string): void {
  db.prepare(`UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ?`).run(
    TRANSIENT_ERROR,
    new Date().toISOString(),
    id,
  );
}

/** Records that the worker is alive. A value of 0 means the worker has stopped. */
export function writeHeartbeat(db: DatabaseSync, value: number = Date.now()): void {
  db.prepare(
    `INSERT INTO meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
  ).run(HEARTBEAT_KEY, String(value));
}

/** True only if the worker wrote a heartbeat within the last `withinMs` milliseconds. */
export function isWorkerUp(db: DatabaseSync, withinMs: number): boolean {
  const row = db.prepare('SELECT value FROM meta WHERE key = ?').get(HEARTBEAT_KEY) as { value: string } | undefined;
  if (!row) return false;
  const at = Number(row.value);
  return at > 0 && Date.now() - at <= withinMs;
}

