import { setTimeout as sleep } from 'node:timers/promises';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase } from './db.ts';
import { MAX_ATTEMPTS } from './jobs.ts';
import {
  claimNextJob,
  completeJob,
  failJob,
  recoverInterruptedJobs,
  requeueJob,
  setProgress,
  writeHeartbeat,
  type ClaimedJob,
} from './store.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1000;
const MIN_RETRY_MS = 250;
const MAX_RETRY_MS = 2000;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function retryDelayMs(): number {
  return MIN_RETRY_MS + Math.floor(Math.random() * (MAX_RETRY_MS - MIN_RETRY_MS + 1));
}

/** Runs one attempt. Returns early, leaving the job `running`, if the worker is asked to stop mid-attempt. */
async function runAttempt(db: DatabaseSync, job: ClaimedJob): Promise<void> {
  if (job.attempts <= job.failAttempts) {
    // Simulated transient failure: fails at the first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return;
    if (job.attempts >= MAX_ATTEMPTS) failJob(db, job.id);
    else requeueJob(db, job.id, retryDelayMs());
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress(db, job.id, step);
  }
  completeJob(db, job.id, job.input.toUpperCase(), job.steps);
}

async function main(): Promise<void> {
  recoverInterruptedJobs(db);
  writeHeartbeat(db);
  const heartbeat = setInterval(() => writeHeartbeat(db), HEARTBEAT_MS);
  console.log('worker started');

  while (!stopping) {
    let claimed: ClaimedJob | undefined;
    try {
      claimed = claimNextJob(db, Date.now());
    } catch (e) {
      console.error(`worker: claim failed: ${e instanceof Error ? e.message : String(e)}`);
      await sleep(POLL_MS);
      continue;
    }
    if (!claimed) {
      await sleep(POLL_MS);
      continue;
    }
    try {
      await runAttempt(db, claimed);
    } catch (e) {
      console.error(`worker: attempt for job ${claimed.id} failed: ${e instanceof Error ? e.message : String(e)}`);
      await sleep(POLL_MS);
    }
  }

  clearInterval(heartbeat);
  writeHeartbeat(db, 0);
  db.close();
  console.log('worker stopped');
}

main().then(
  () => process.exit(0),
  (e: unknown) => {
    console.error(`worker: fatal: ${e instanceof Error ? e.message : String(e)}`);
    process.exit(1);
  },
);

