import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase } from './db.ts';
import { IDEMPOTENCY_KEY_PATTERN, parseSubmission, type FieldError } from './jobs.ts';
import { getJob, isWorkerUp, listJobs, submitJob } from './store.ts';

const MAX_BODY_BYTES = 16 * 1024;
const WORKER_HEARTBEAT_WINDOW_MS = 3000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  sendJson(res, status, { error: { code, message, ...(fields ? { fields } : {}) } }, headers);
}

function methodNotAllowed(res: ServerResponse, allow: string[]): void {
  sendError(res, 405, 'method_not_allowed', 'method not allowed for this path', undefined, { allow: allow.join(', ') });
}

/** Reads the request body. Resolves undefined if it exceeds the size limit. */
function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  return header !== undefined && header.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const contentType = req.headers['content-type'];
  if (!isJsonContentType(contentType)) {
    return sendError(res, 400, 'invalid_request', 'Content-Type must be application/json', [
      { field: 'body', message: 'Content-Type must be application/json' },
    ]);
  }
  if (raw === undefined) {
    return sendError(res, 400, 'invalid_request', 'request body is too large', [{ field: 'body', message: 'body is too large' }]);
  }

  const fields: FieldError[] = [];
  let submission: ReturnType<typeof parseSubmission> | undefined;
  try {
    submission = parseSubmission(JSON.parse(raw));
  } catch {
    fields.push({ field: 'body', message: 'body is not valid JSON' });
  }
  if (submission && !submission.ok) fields.push(...submission.fields);

  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(keyHeader)) {
    fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  if (fields.length > 0 || !submission || !submission.ok) {
    return sendError(res, 400, 'invalid_request', 'invalid job submission', fields);
  }

  const outcome = submitJob(db, submission.value, keyHeader);
  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload');
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

function handleRequest(req: IncomingMessage, res: ServerResponse): void {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const worker = isWorkerUp(db, WORKER_HEARTBEAT_WINDOW_MS) ? 'up' : 'down';
    return sendJson(res, 200, { status: 'ok', worker });
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobs(db) });
    if (method === 'POST') {
      void handleCreateJob(req, res).catch((e: unknown) => {
        console.error(`server: create job failed: ${e instanceof Error ? e.message : String(e)}`);
        if (!res.headersSent) sendError(res, 500, 'internal_error', 'internal server error');
      });
      return;
    }
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'job not found');
    }
    const job = getJob(db, id);
    if (!job) return sendError(res, 404, 'not_found', 'job not found');
    return sendJson(res, 200, job);
  }

  // Drain any request body so the connection can be reused for the 404.
  req.resume();
  sendError(res, 404, 'not_found', 'not found');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  try {
    handleRequest(req, res);
  } catch (e) {
    console.error(`server: request failed: ${e instanceof Error ? e.message : String(e)}`);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'internal server error');
  }
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

